    images: [{ key: "rcr-closed-chain-weight-shift-1", ar: "ثلاثُ لوحات: رجلٌ يستند بيديه على طاولة، ثمّ على حائط، ثمّ على الأربع فوق سجّادة صلاة والوزنُ على اليدين", en: "Three panels: a man leaning on his hands on a table, then on a wall, then on all fours on a prayer mat with the weight through both hands", search: "closed chain shoulder weight shift table wall quadruped" }],
